/* CommonHome Canvas — built-in motivational quotes library.
 *
 * The default source for the quote widget, in the spirit of Momentum's quote
 * feed but shipped locally: no network call, no account, no tracking. A
 * household can add its own entries later (Phase 2 persistence); this file is
 * the seed set.
 *
 * ATTRIBUTION DOCTRINE APPLIES TO WORDS TOO. Every quote names its author, and
 * this set deliberately avoids the internet's famous misattributions (the
 * "Gandhi" change quote, the "Einstein" insanity quote, the "Twain" quotes he
 * never wrote). Where a quote is traditional or its author is genuinely
 * unknown, it says so rather than borrowing a famous name. Sources are the
 * author's published work wherever one exists.
 *
 * Kid-safe: this renders on a living-room wall. Nothing here needs a caveat.
 */

export type Quote = {
  text: string;
  author: string;
  /** Work or context, shown in details views; optional. */
  source?: string;
};

